'use strict';

// MODULES //

var bench = require( '@stdlib/bench-harness' );
var Complex64 = require( '@stdlib/complex-float32-ctor' );
var randu = require( '@stdlib/random-base-randu' );
var isArrayLike = require( '@stdlib/assert-is-array-like' );
var pkg = require( './../package.json' ).name;
var reim = require( './../lib' );


// MAIN //

bench( pkg, function benchmark( b ) {
	var values;
	var arr;
	var i;

	values = [
		new Complex64( randu(), randu() ),
		new Complex64( randu(), randu() ),
		new Complex64( randu(), randu() )
	];

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		arr = reim( values[ i%values.length ] );
		if ( arr.length === 0 ) {
			b.fail( 'should not be empty' );
		}
	}
	b.toc();
	if ( !isArrayLike( arr ) ) {
		b.fail( 'should return an array' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});","lineStart":1,"lineEnd":57,"totalLines":57,"truncated":false}},"title":"repos/pc-lib-3456/complex-float32-reim/benchmark/benchmark.js","time":{"start":1783264195638,"end":1783264195649}},"id":"prt_f32d4332d001TH1YXjtEyIBn9Y","sessionID":"ses_0cd2c777fffeN8yWi860nGoJ91","messageID":"msg_f32d42a8d001tPrnRpRZoKn60s"}}

